window.ATLAS.addDetails("circuits.edges",{"edges":{
"blackbody-radiation:photoelectric-effect":{"type":"connection","label":{"zh":"两处都出现能量量子","en":"Energy quanta appear in both"},"reason":{"zh":"黑体辐射里 hν 的能量份解决了紫外发散，光电效应里同样的 hν 解释了光电子的最大动能，二者互相印证量子化。","en":"The energy unit hν resolves the ultraviolet divergence in blackbody radiation, and the same hν explains the maximum photoelectron energy, so the two support each other."},"source":"../physics/modern/blackbody-radiation/#step5"},
"boost:feedback":{"type":"application","label":{"zh":"用测量调节占空比","en":"uses measurements to adjust duty"},"reason":{"zh":"实际稳压器可测量输出并调节占空比；本课只解释此接口，不模拟控制器。","en":"A real regulator can measure output and adjust duty; this lesson explains the connection without simulating a controller."},"source":"../physics/circuits/power-converters/#step6"},
"capacitor:boost":{"type":"application","label":{"zh":"在开关闭合时供电","en":"supplies load during ON"},"reason":{"zh":"开关闭合时二极管截止，负载由输出电容供电。","en":"During ON the diode blocks, and the output capacitor supplies the load."},"source":"../physics/circuits/power-converters/#step5"},
"capacitor:buck":{"type":"application","label":{"zh":"补偿电流差","en":"balances current difference"},"reason":{"zh":"电感电流与负载电流的差流入或流出输出电容。","en":"The difference between inductor and load current charges or discharges the output capacitor."},"source":"../physics/circuits/power-converters/#step4"},
"carnot-cycle:work-energy":{"type":"connection","label":{"zh":"Q_h = W + Q_c 的能量账","en":"The energy ledger Q_h = W + Q_c"},"reason":{"zh":"一圈回来内能不变，吸的热一部分变成功、其余排给冷源，是能量守恒在热机上的账本。","en":"After one full cycle the internal energy is unchanged, so the heat taken in becomes work or is rejected to the cold sink, energy conservation applied to a heat engine."},"source":"../physics/thermal/carnot-cycle/#step3"},
"derivative:capacitor":{"type":"application","label":{"zh":"把电流读成电压变化率","en":"reads current as voltage rate"},"reason":{"zh":"对恒定理想电容，q=Cv且i=dq/dt，所以i=C·dv/dt；电流流入电压标正的端子。零电流保持已有电压；这不是漏电或电阻充电模型，也不是必修顺序。","en":"For constant ideal capacitance, q=Cv and i=dq/dt give i=C·dv/dt, with current entering the voltage-positive terminal. Zero current preserves existing voltage; this is not leakage or resistive charging, nor a mandatory learning order."},"source":"https://openstax.org/books/university-physics-volume-2/pages/9-1-electrical-current"},
"derivative:electromagnetic-induction":{"type":"application","label":{"zh":"电压是磁通量的变化率","en":"Voltage is the rate of change of flux"},"reason":{"zh":"磁通量变化越快，感应电动势越大——导数就是“变化快慢”的量度，所以法拉第定律写成 ε = −N dΦ/dt：它量的正是磁通量被推着走的速度。","en":"The faster the flux changes, the larger the induced emf — a derivative is exactly the measure of 'how fast it changes', so Faraday's law is written ε = −N dΦ/dt: it measures the speed at which the flux is being pushed."},"source":"../physics/electromagnetism/electromagnetic-induction/#step1"},
"electric-fields:electrochemistry":{"type":"application","label":{"zh":"电势差","en":"Potential difference"},"reason":{"zh":"电极电势 E° 就是单位电荷在电极处具有的能量差——与电场页的电势是同一个量，只不过这里的“位置”换成了电极表面。","en":"An electrode potential E° is the energy difference per unit charge at the electrode — the same quantity as potential in the electric-fields lesson, only with the 'location' replaced by the electrode surface."},"source":"../chemistry/reactions/electrochemistry/#step0"},
"electric-fields:electromagnetic-induction":{"type":"connection","label":{"zh":"静电场与感应电场","en":"Electrostatic versus induced fields"},"reason":{"zh":"电场页的电场来自静止电荷、有势可循；感应电动势同样是电场在回路上的推动，却绕圈不回头——感应把“电场”从有势推广到了无势。","en":"The electric-fields lesson's field comes from still charges and has a potential; induced emf is equally an electric push around a loop, but it circles without returning — induction extends the 'electric field' from having a potential to not having one."},"source":"../physics/electromagnetism/electromagnetic-induction/#step2"},
"electric-fields:magnetic-force":{"type":"connection","label":{"zh":"电力与磁力对照","en":"Electric versus magnetic force"},"reason":{"zh":"第 4 步让电力 qE 与磁力 qvB 方向相反，平衡时 v = E/B。","en":"Step 4 sets the electric force qE against the magnetic force qvB; they balance at v = E/B."},"source":"../physics/electromagnetism/magnetic-force/#step4"},
"electric-fields:molecular-shapes":{"type":"application","label":{"zh":"同号电荷互相排斥","en":"Like charges repel"},"reason":{"zh":"电子对在球面上被 1/r² 的静电斥力推开，排成最低能量的队形。","en":"Electron pairs on the sphere are pushed apart by a 1/r² electrostatic repulsion and settle into the lowest-energy arrangement."},"source":"../chemistry/matter/molecular-shapes/#step1"},
"electric-fields:periodic-trends":{"type":"application","label":{"zh":"核电荷吸引电子","en":"Nuclear charge attracts electrons"},"reason":{"zh":"有效核电荷越大，对外层电子的静电吸引越强，半径越小。","en":"A larger effective nuclear charge attracts outer electrons more strongly and shrinks the radius."},"source":"../chemistry/matter/periodic-trends/#step2"},
"electric-fields:work-energy":{"type":"connection","label":{"zh":"势能与动能互换","en":"Potential and kinetic energy trade"},"reason":{"zh":"试探电荷运动中动能加势能保持不变，与功能关系同一账本。","en":"A test charge's kinetic plus potential energy stays constant, the same ledger as the work–energy relation."},"source":"../physics/electromagnetism/electric-fields/#step4"},
"electrochemistry:electromagnetic-induction":{"type":"connection","label":{"zh":"两种得到电压的办法","en":"Two ways to get a voltage"},"reason":{"zh":"原电池靠化学反应给出电动势，感应靠磁通量变化给出电动势，两者都向外电路输出电压。","en":"A galvanic cell gets its emf from a chemical reaction and induction gets it from a changing flux; both drive a voltage into an external circuit."},"source":"../chemistry/reactions/electrochemistry/#step0"},
"electrochemistry:probability":{"type":"connection","label":{"zh":"能斯特方程里的对数","en":"The logarithm in the Nernst equation"},"reason":{"zh":"能斯特方程的对数形式来自玻尔兹曼因子：浓度比改一个数量级，电压只动一个固定台阶——电压与 log Q 成直线，根子是概率的指数律。","en":"The Nernst equation's logarithmic form comes from the Boltzmann factor: change the concentration ratio by one order of magnitude and the voltage moves by one fixed step — voltage linear in log Q is rooted in probability's exponential law."},"source":"../chemistry/reactions/electrochemistry/#step2"},
"electromagnetic-induction:oscillation":{"type":"connection","label":{"zh":"转动线圈给出正弦","en":"A spinning coil gives a sine"},"reason":{"zh":"匀速转动使磁通量按余弦变化，感应电动势是同频率的正弦波。","en":"Uniform rotation makes the flux a cosine, so the emf is a sine at the same frequency."},"source":"../physics/electromagnetism/electromagnetic-induction/#step4"},
"inductor:boost":{"type":"application","label":{"zh":"向更高电压供能","en":"feeds a higher voltage"},"reason":{"zh":"关断时电感电流下降，电感右端电势升高，电源与电感共同供能。","en":"During OFF, current falls and the right inductor terminal rises; source and inductor deliver energy together."},"source":"../physics/circuits/power-converters/#step5"},
"inductor:buck":{"type":"application","label":{"zh":"保持连续电流","en":"maintains current"},"reason":{"zh":"开关断开后，电感通过续流二极管继续向输出送电。","en":"When the switch opens, the inductor continues delivering current through the freewheel diode."},"source":"../physics/circuits/power-converters/#step4"},
"inductor:capacitor":{"type":"connection","label":{"zh":"互补地记住状态","en":"store complementary states"},"reason":{"zh":"电感记住电流，电容记住电压；两者在电路中交换储能，但元件定律不同。","en":"Inductors retain current and capacitors retain voltage. Both exchange stored energy, under different component laws."},"source":"../physics/circuits/power-converters/#step2"},
"integral:inductor":{"type":"application","label":{"zh":"把电压面积换成电流改变量","en":"maps voltage area to current change"},"reason":{"zh":"恒定理想L、被动端口符号下，∫vL dt=L[iL(b)−iL(a)]。有符号伏秒决定电流改变量，不是能量；重复周期净面积为零时电流回到起值，不必为零。暂态区间不要求平衡。","en":"For constant ideal L with passive terminal signs, ∫vL dt=L[iL(b)−iL(a)]. Signed voltseconds determine current change, not energy. Zero net area over a repeating period returns current to its initial value, not necessarily zero. Transient intervals need not balance."},"source":"https://wiki.analog.com/university/courses/electronics/buck_converter_basics"},
"kinetic-theory:blackbody-radiation":{"type":"foundation","label":{"zh":"温度是热能尺度 kT","en":"Temperature sets the thermal scale kT"},"reason":{"zh":"黑体辐射把一份光量子能量与热能 kT 比较，kT 正是气体动理论里温度对应的微观能量尺度。","en":"Blackbody radiation compares one light quantum with the thermal energy kT, the same microscopic energy scale that temperature has in kinetic theory."},"source":"../physics/modern/blackbody-radiation/#step5"},
"magnetic-force:oscillation":{"type":"connection","label":{"zh":"圆周运动的投影是振动","en":"A circle projects to an oscillation"},"reason":{"zh":"粒子绕圆匀速运动，其一个坐标随时间按正弦变化，周期与速度无关。","en":"Uniform motion on a circle makes each coordinate vary sinusoidally, with a period independent of speed."},"source":"../physics/electromagnetism/magnetic-force/#step2"},
"magnets:vectors":{"type":"representation","label":{"zh":"场是每点一个向量","en":"A field is a vector at every point"},"reason":{"zh":"指南针和铁屑小线段显示的是每个位置磁场的方向和大小，也就是给每个点配一个向量。","en":"The compasses and filings show the direction and size of the field at each position, that is, a vector assigned to every point."},"source":"../physics/electromagnetism/magnets/#step3"},
"ohms-law:series-parallel":{"type":"application","label":{"zh":"逐段用 I = U/R","en":"Applying I = V/R piece by piece"},"reason":{"zh":"第 4 步混联电路里每一段都用欧姆定律算电流和电压，并用 V₁+V₂₃=12 V 与 I₂+I₃=I 核对。","en":"In step 4 every part of the mixed circuit uses Ohm’s law, checked against V₁+V₂₃ = 12 V and I₂+I₃ = I."},"source":"../physics/circuits/series-parallel/#step4"},
"ohms-law:work-energy":{"type":"application","label":{"zh":"功率 P = UI","en":"Power P = VI"},"reason":{"zh":"第 3 步用同一条电阻看功率：保持电压或保持电流不变，随电阻变化的方向相反。","en":"Step 3 uses the same resistor to study power: holding voltage or holding current fixed gives opposite trends as R changes."},"source":"../physics/circuits/ohms-law/#step3"},
"power:capacitor":{"type":"foundation","label":{"zh":"解释储能","en":"explains storage"},"reason":{"zh":"电容存的能量只能靠功率进出改变，功率等于电压乘电流——它告诉你电容充放电有多快，而不是只报一个静态数值。","en":"A capacitor's stored energy changes only through power in or out, and power equals voltage times current — it tells how fast the capacitor charges or discharges, not just a static number."},"source":"../physics/circuits/power-converters/#step2"},
"power:inductor":{"type":"foundation","label":{"zh":"解释储能","en":"explains storage"},"reason":{"zh":"电感电流有惯性、不能突变：功率进出改变的是磁场储能——P=VI 讲的是电流被推快或推慢的速度，而不是某一刻的存量。","en":"An inductor's current has inertia and cannot jump: power in or out changes the stored magnetic energy — P=VI tells how fast the current is pushed up or slowed down, not how much is stored at one instant."},"source":"../physics/circuits/power-converters/#step1"},
"pwm:boost":{"type":"application","label":{"zh":"设定理想升压比例","en":"sets ideal boost ratio"},"reason":{"zh":"在恒定直流输入、理想 CCM 的小纹波周期稳态近似下，平均电压 ⟨Vout⟩ ≈ Vin/(1−D)，0<D<1。","en":"With constant DC input, ideal CCM and the small-ripple periodic steady-state approximation, ⟨Vout⟩ ≈ Vin/(1−D), with0<D<1."},"source":"../physics/circuits/power-converters/#step5"},
"pwm:buck":{"type":"application","label":{"zh":"设定理想电压比例","en":"sets ideal voltage ratio"},"reason":{"zh":"占空比 D 就是开关接通输入的时间占比：伏秒平衡下，输出平均电压等于 D·Vin——调 D 就是调输出，D 越大输出越高。","en":"The duty ratio D is the fraction of time the switch connects the input: volt-second balance then makes the average output D·Vin — turning D turns the output, larger D giving higher output."},"source":"../physics/circuits/power-converters/#step4"},
"simple-circuits:ohms-law":{"type":"foundation","label":{"zh":"回路里的电流有多大","en":"How big the loop current is"},"reason":{"zh":"简单电路只说了闭合回路才有电流，本页第 0 步进一步量化：电流与电压成正比、与电阻成反比。","en":"Simple circuits only says a closed loop is needed for current; step 0 here puts numbers on it: current is proportional to voltage and inversely proportional to resistance."},"source":"../physics/circuits/ohms-law/#step0"},
"simple-circuits:power":{"type":"foundation","label":{"zh":"灯泡的亮度就是功率","en":"Bulb brightness is power"},"reason":{"zh":"第 4 步用 P = I²R 比较灯泡亮度并判断是否超过额定功率，这是电路里“能量如何被用掉”的最简单例子。","en":"Step 4 compares bulb brightness with P = I²R against a rated power, the simplest example of where a circuit's energy goes."},"source":"../physics/circuits/simple-circuits/#step4"},
"simple-circuits:series-parallel":{"type":"foundation","label":{"zh":"一个回路扩展到分叉","en":"From one loop to branching ones"},"reason":{"zh":"简单电路只有一个回路；本页第 0、1 步把它扩展为串联（一条通路）与并联（多条通路）。","en":"Simple circuits has one loop; steps 0 and 1 here extend it to series (one path) and parallel (several paths)."},"source":"../physics/circuits/series-parallel/#step0"},
"superposition:electric-fields":{"type":"application","label":{"zh":"场的叠加","en":"Fields superpose"},"reason":{"zh":"多个电荷的电场逐点矢量相加，是叠加原理的一个具体例子。","en":"The fields of several charges add as vectors point by point, a concrete case of the superposition principle."},"source":"../physics/electromagnetism/electric-fields/#step1"},
"switch-diode:boost":{"type":"application","label":{"zh":"交替储能与放能","en":"alternates storage and release"},"reason":{"zh":"开关闭合给电感储能，断开时电流经二极管流向输出。","en":"ON stores energy in the inductor; OFF routes current through the diode to the output."},"source":"../physics/circuits/power-converters/#step5"},
"switch-diode:buck":{"type":"application","label":{"zh":"建立两条电流路径","en":"establishes two current paths"},"reason":{"zh":"开关闭合连接输入；开关断开时续流二极管提供回路。","en":"The closed switch connects the input; the freewheel diode provides the OFF loop."},"source":"../physics/circuits/power-converters/#step4"},
"vectors:electric-fields":{"type":"representation","label":{"zh":"场是矢量场","en":"A field is a vector field"},"reason":{"zh":"每一点的 E 都有大小和方向，用箭头表示并按矢量相加。","en":"E has a size and direction at every point, drawn as arrows and added as vectors."},"source":"../physics/electromagnetism/electric-fields/#step0"},
"vectors:magnetic-force":{"type":"representation","label":{"zh":"叉乘给出力的方向","en":"The cross product gives the force direction"},"reason":{"zh":"磁力方向既不沿 v 也不沿 B，而是同时垂直于两者——没有矢量叉乘就说不清这个方向，右手定则就是它的操作版。","en":"The magnetic force points neither along v nor along B, but perpendicular to both — without the vector cross product there is no way to state that direction, and the right-hand rule is its working version."},"source":"../physics/electromagnetism/magnetic-force/#step0"},
"work-energy:carnot-cycle":{"type":"application","label":{"zh":"功是 p–V 曲线下面积","en":"Work as area under p–V"},"reason":{"zh":"气体对外做功 W = ∫P dV，是功—能量关系在气体上的具体形式；一圈的净功等于回路围出的面积。","en":"The work done by a gas, W = ∫P dV, is the work–energy relation for a gas; the net work of a cycle equals the area enclosed by the loop."},"source":"../physics/thermal/carnot-cycle/#step0"}
}});
